SELECT pp.status, CASE WHEN (pp.entry_price - pp.stop_loss) / NULLIF(s.atr_at_signal, 0) < 2.5 THEN '<2.5ATR' WHEN (pp.entry_price - pp.stop_loss) / NULLIF(s.atr_at_signal, 0) < 4 THEN '2.5-4ATR' WHEN (pp.entry_price - pp.stop_loss) / NULLIF(s.atr_at_signal, 0) < 7 THEN '4-7ATR' ELSE '>=7ATR' END AS stop_atr_band, COUNT(*) AS n, SUM(pp.realized_pnl < 0) AS losers, SUM(pp.realized_pnl) AS net_pnl, AVG(TIMESTAMPDIFF(SECOND, pp.opened_at, pp.closed_at)) AS avg_hold_s FROM crypto_ai.paper_position pp JOIN crypto_ai.trade_signal s ON s.id = pp.signal_id WHERE pp.status IN ('CLOSED','STOPPED') AND s.atr_at_signal > 0 GROUP BY pp.status, stop_atr_band ORDER BY pp.status, stop_atr_band LIMIT 20